  'aiworkspace.demo.quarterly.introText': 'Dies ist eine gewöhnliche Umsatztabelle für Q2 2026: Umsatz, Kosten, Ziel und Umsatz des Vorquartals nach Region und Produkt. Sie können die Zahlen direkt im Datenquellenmodus ändern oder im Wunschblock auf dem Canvas in einem Satz beschreiben, welche Analyse Sie möchten, und dann dreimal dessen Schaltfläche drücken: Analysieren, Makro schreiben, Makro ausführen. Jeder Schritt schreibt sein Ergebnis, sobald er fertig ist; entspricht eines nicht Ihren Vorstellungen, gehen Sie zum vorigen Tab zurück und führen es erneut aus oder machen es rückgängig. Der blaue gestrichelte Pfeil zeigt, was der Wunsch liest, die orangefarbenen, was er erzeugt hat. Wenn sich die Daten ändern, führen Sie das Makro erneut aus.',
