  'aiworkspace.demo.film.howto.text': 'Ein Generierungsablauf von links nach rechts, in dem jeder Knoten ein gewöhnliches Canvas-Objekt ist: Links stehen Drehbuch, Figurentabelle und Stil, die Sie direkt bearbeiten können; jede Stufe ist ein Wunschblock, und auf jeder Karte drücken Sie nacheinander Analysieren, Makro schreiben und Makro ausführen – jeder Schritt schreibt sein Ergebnis, sobald er fertig ist. Was eine Stufe erzeugt, ist die Eingabe der nächsten; führen Sie die Stufen daher von links nach rechts aus. Blaue gestrichelte Pfeile zeigen von dem, was ein Wunsch liest; orangefarbene zu dem, was er erzeugt hat. Wenn Sie die Figurentabelle oder das Drehbuch ändern, werden die nachgelagerten Ergebnisse als veraltet markiert; führen Sie sie nacheinander erneut aus. Die Bilder und das Video werden von den KI-Modellen der Zone erzeugt.',
  'aiworkspace.demo.film.surface': 'Kurzfilm-Workflow',
  'aiworkspace.demo.film.wish1.title': 'Wunschblock ①: Figurenbögen erzeugen',
  'aiworkspace.demo.film.wish1.prompt': 'Erzeuge aus der Tabelle „{{characters}}“ und „{{style}}“ für jede Figur einen Figurenbogen im Hochformat mit einer kurzen Profilnotiz. Behalte Hauptfarbe und Requisiten jeder Figur bei, damit das Storyboard sie später verwenden kann.',
  'aiworkspace.demo.film.wish1.output': 'Figurenbögen',
  'aiworkspace.demo.film.wish2.title': 'Wunschblock ②: Storyboard erzeugen',
  'aiworkspace.demo.film.wish2.prompt': 'Erzeuge aus den Szenen von „{{script}}“ zusammen mit „{{sheets}}“ und „{{style}}“ ein Storyboard: eine Einstellung pro Szene; gib eine Einstellungsliste (Einstellungsnr., Szene, Einstellungsgröße, Figuren, Handlung, Dauer) und ein Bild für jede Einstellung aus.',
  'aiworkspace.demo.film.wish2.output': 'Storyboard',
  'aiworkspace.demo.film.wish3.title': 'Wunschblock ③: Vorschau des Endschnitts erzeugen',
  'aiworkspace.demo.film.wish3.prompt': 'Erzeuge aus „{{storyboard}}“ ein Vorschauvideo des Endschnitts: ein zusammenhängender Clip von etwa 8 Sekunden (16:9), der den Einstellungen in ihrer Reihenfolge folgt und das Bild der ersten Einstellung als Referenzbild verwendet; schreibe außerdem eine Notiz mit der Anzahl der Einstellungen und der Gesamtdauer der Einstellungsliste.',
  'aiworkspace.demo.film.wish3.output': 'Endschnitt',
  'aiworkspace.demo.film.commit.data': 'Drehbuch, Figurentabelle, Stil',
